type LootType=keyof typeof lootSeeds;
const lootTypes=Object.keys(lootSeeds) as LootType[];
function buildLootCatalog(kind:LootType){const seed=lootSeeds[kind];const out:{name:string;effect:string}[]=[];for(let i=0;i<2000;i++){const a=seed.adjs[i%seed.adjs.length];const n=seed.names[Math.floor(i/seed.adjs.length)%seed.names.length];const effect=seed.effects[Math.floor(i/17)%seed.effects.length];out.push({name:`${a} ${n} ${i+1}`,effect});}return out}
const lootCatalogs=Object.fromEntries(lootTypes.map(k=>[k,buildLootCatalog(k)])) as Record<LootType,{name:string;effect:string}[]>;
function GM(){const [kind,setKind]=useState<LootType>("Weapon");const [rarity,setRarity]=useState("Any");const [floor,setFloor]=useState(3);const [count,setCount]=useState(1);const [theme,setTheme]=useState("Dungeon");const [out,setOut]=useState<{name:string;effect:string;rarity:string;floor:number;theme:string}[]>([]);const generate=()=>{const catalog=lootCatalogs[kind];const wanted=Math.max(1,Math.min(20,count));const shuffled=[...catalog].sort(()=>Math.random()-0.5);const seen=new Set<string>();const results=[];for(const item of shuffled){if(results.length>=wanted)break;if(seen.has(item.name))continue;seen.add(item.name);const rarityText=rarity==="Any"?["Common","Uncommon","Rare","Very Rare","Legendary"][Math.floor(Math.random()*5)]:rarity;results.push({...item,rarity:rarityText,floor,theme})}setOut(results)};return <><section className="section-head"><div><h2>GM Command Center</h2><p>Controlled generators with a large original loot catalog. Each loot type contains 2,000 generated items with an effect and a little dungeon humor.</p></div></section><Card title="Loot Generator"><div className="formgrid"><label className="field"><span>Loot Type</span><select value={kind} onChange={e=>setKind(e.target.value as LootType)}>{lootTypes.map(x=><option key={x}>{x}</option>)}</select></label><label className="field"><span>Rarity</span><select value={rarity} onChange={e=>setRarity(e.target.value)}>{["Any","Common","Uncommon","Rare","Very Rare","Legendary"].map(x=><option key={x}>{x}</option>)}</select></label><Field label="Floor" type="number" value={floor} onChange={v=>setFloor(Math.max(1,Number(v)||1))}/><label className="field"><span>Number of Drops</span><input type="number" min="1" max="20" value={count===0?"":count} onChange={e=>{const raw=e.target.value;if(raw===""){setCount(0);return}const n=Number(raw);if(Number.isFinite(n))setCount(Math.max(1,Math.min(20,n)))}} onBlur={()=>setCount(Math.max(1,Math.min(20,count||1)))}/></label><label className="field"><span>Theme</span><select value={theme} onChange={e=>setTheme(e.target.value)}>{["Dungeon","Frozen","Desert","Urban","Arcane","Organic"].map(x=><option key={x}>{x}</option>)}</select></label></div><p className="hint">{kind}: 2,000-item catalog • every result includes what it does.</p><button onClick={generate}>🎁 Generate Loot</button>{out.length>0&&<div className="loot-results">{out.map((x,i)=><div className="generator-result" key={i}><b>Drop {i+1}: {x.rarity} {x.name}</b><span>Floor {x.floor} • {x.theme}</span><p><strong>What it does:</strong> {x.effect}</p></div>)}</div>}</Card><div className="gm-grid">{["⚔️ Encounter","🧑 NPC","📜 Quest","🚪 Room"].map(k=><Card key={k} title={k}><button onClick={()=>setOut([{name:k.replace(/^[^ ]+ /,""),effect:`Generated for Floor ${floor}. Complication: ${["hidden ambush","unstable terrain","ticking threat","tempting reward"][Math.floor(Math.random()*4)]}. Someone definitely thought this was a good idea.`,rarity:"Generated",floor,theme}])}>Generate</button></Card>)}</div></>}

function normalizeText(s:string){return s.toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
function Rulebook(){const [pages,setPages]=useState<{page:number;text:string}[]>([]);const [name,setName]=useState("");const [q,setQ]=useState("");const [matches,setMatches]=useState<{page:number;text:string;full:string;score:number}[]>([]);const [busy,setBusy]=useState(false);const [err,setErr]=useState("");const [notice,setNotice]=useState("");const upload=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;setBusy(true);setErr("");setNotice("");setMatches([]);try{if(f.type!=="application/pdf"&&!f.name.toLowerCase().endsWith(".pdf"))throw new Error("Please choose a PDF file.");if(f.size>1024*1024*1024)throw new Error("That PDF is over 1 GB. Please use a smaller copy.");const buf=await f.arrayBuffer();if(new TextDecoder().decode(new Uint8Array(buf.slice(0,5)))!=="%PDF-")throw new Error("That file does not appear to be a valid PDF.");const pdfjs=await import("pdfjs-dist");pdfjs.GlobalWorkerOptions.workerSrc=new URL("pdfjs-dist/build/pdf.worker.min.mjs",import.meta.url).toString();const pdf=await pdfjs.getDocument({data:buf,disableAutoFetch:false,disableStream:false}).promise;const rows:{page:number;text:string}[]=[];for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const c=await p.getTextContent();const text=c.items.map((x:any)=>x.str||"").join(" ").replace(/\s+/g," ").trim();if(text)rows.push({page:i,text})}if(!rows.length)throw new Error("The PDF loaded, but no selectable text was found. A scanned/image-only PDF needs OCR support.");setPages(rows);setName(f.name);setNotice(`✓ ${rows.length} pages indexed in your browser. Large PDFs are supported up to 1 GB. Your PDF is not bundled with the app.`)}catch(ex){setErr(ex instanceof Error?ex.message:"Could not read PDF.")}finally{setBusy(false)}};const answer=()=>{const query=normalizeText(q);if(!query||!pages.length)return;const tokens=query.split(" ").filter(w=>w.length>1);const movement=/move|movement|speed|feet|foot|step/.test(query);const scored=pages.flatMap(p=>p.text.split(/(?<=[.!?])\s+/).map(s=>s.trim()).filter(s=>s.length>20).map(s=>{let score=0;const low=normalizeText(s);for(const w of tokens)if(low.includes(w))score+=3;if(movement&&/20 feet|10 feet|60 feet|move action|step/.test(low))score+=18;return {page:p.page,text:s,full:p.text,score}})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);const unique=[];const seen=new Set<string>();for(const m of scored){const key=`${m.page}|${m.text}`;if(!seen.has(key)){seen.add(key);unique.push(m)}if(unique.length===5)break}setMatches(unique)};const answerText=useMemo(()=>{const n=normalizeText(q);if(/move|movement|speed|feet|foot/.test(n))return "A crawler normally moves 20 feet with a Move Action. Each Action also includes a free 10-foot Step, so using both Actions to move can total 60 feet on a turn.";if(/level|leveling|level up/.test(n))return "Each party member gains 1 level every 2 hours of play.";return matches[0]?`The strongest matching passage is on page ${matches[0].page}. Read the source below rather than treating an unsupported guess as a rule.` : ""},[q,matches]);return <><section className="section-head"><div><h2>Rulebook Assistant</h2><p>Ask a normal question. Get the clearest supported answer first, then the source.</p></div><span className="pill">{name||"No book loaded"}</span></section><Card title="1. Load Rulebook"><div className="upload">📖 Choose your licensed PDF<input type="file" accept="application/pdf" onChange={upload}/></div>{busy&&<p className="hint">Reading and indexing the PDF… keep this tab open.</p>}{notice&&<p className="success">{notice}</p>}{err&&<p className="error">{err}</p>}</Card><Card title="2. Ask"><textarea className="question" placeholder="Example: How many feet can I move?" value={q} onChange={e=>setQ(e.target.value)}/><div className="question-hints"><button onClick={()=>setQ("How many feet can I move?")}>🏃 Movement</button><button onClick={()=>setQ("How does leveling work?")}>📈 Leveling</button><button onClick={()=>setQ("How does health work?")}>❤️ Health</button></div><button className="ask" disabled={!pages.length||busy||!q.trim()} onClick={answer}>🔎 Answer My Question</button>{q.trim()&&answerText&&<div className="answerbox"><div className="answer-title"><div><span className="eyebrow">ANSWER</span><h3>{answerText}</h3></div>{matches[0]&&<span className="pill">Page {matches[0].page}</span>}</div>{matches[0]&&<><div className="best-source"><b>Source • Page {matches[0].page}</b><p>{matches[0].text}</p></div>{matches.length>1&&<details><summary>Show other relevant passages</summary>{matches.slice(1).map((m,i)=><div className="source compact" key={i}><b>Page {m.page}</b><textarea readOnly value={m.text}/></div>)}</details>}<details><summary>Show full source page</summary><textarea readOnly value={matches[0].full}/></details></>}</div>}{pages.length>0&&matches.length===0&&q&&<p className="hint">No matching passage yet. Try the exact rule name or a shorter question.</p>}</Card></>}
function DataTools({c,setC}:{c:Character;setC:React.Dispatch<React.SetStateAction<Character>>}){const [msg,setMsg]=useState("");const exportData=()=>{const blob=new Blob([JSON.stringify(c,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${(c.name||"crawler").replace(/[^a-z0-9]+/gi,"-").toLowerCase()}-backup.json`;a.click();URL.revokeObjectURL(a.href);setMsg("Backup exported.")};return <Card title="Backup & Restore"><div className="buttonrow"><button onClick={exportData}>⬇️ Export Character</button><div className="buttonlike">⬆️ Import Character<input type="file" accept="application/json,.json" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());setC(normalize(obj));setMsg("Character restored. Review it before play.")}catch{setMsg("That backup could not be read.")}}}/></div></div>{msg&&<p className="hint">{msg}</p>}</Card>}

function AccountPage({c,setC}:{c:Character;setC:React.Dispatch<React.SetStateAction<Character>>}){
 const [mode,setMode]=useState<"login"|"signup">("signup");
 const [email,setEmail]=useState(()=>localStorage.getItem("cc-email")||"");
 const [name,setName]=useState(()=>localStorage.getItem("cc-user")||"");
 const [user,setUser]=useState<any>(null);
 const [pro,setPro]=useState(()=>localStorage.getItem("cc-protest")==="1");
 const [cloudMsg,setCloudMsg]=useState("");
 useEffect(()=>{let active=true;cloudUser().then(u=>{if(active){setUser(u);if(u?.email)setEmail(u.email);if(u?.user_metadata?.display_name)setName(u.user_metadata.display_name)}});const sub=cloudAuthChanges(u=>{setUser(u);if(u?.email){setEmail(u.email);localStorage.setItem("cc-email",u.email)}if(u?.user_metadata?.display_name){setName(u.user_metadata.display_name);localStorage.setItem("cc-user",u.user_metadata.display_name)}});return()=>{active=false;sub.unsubscribe()}},[]);
 const save=async()=>{setCloudMsg("");try{if(!email.trim()||password.length<6)throw new Error("Enter an email and a password of at least 6 characters.");if(mode==="signup"){const d=await cloudSignUp(email.trim(),password,name.trim());if(!d.session)setCloudMsg("✓ Account created. Check your email to confirm, then log in.");else setCloudMsg("✓ Account created and signed in.")}else{await cloudSignIn(email.trim(),password);setCloudMsg("✓ Signed in. Cloud sync is ready.")}localStorage.setItem("cc-user",name.trim()||email.split("@")[0]);localStorage.setItem("cc-email",email.trim())}catch(e){setCloudMsg(e instanceof Error?e.message:"Authentication failed.")}};
 const [password,setPassword]=useState("");
 const signout=async()=>{try{await cloudSignOut();setUser(null);setCloudMsg("Signed out.")}catch(e){setCloudMsg(e instanceof Error?e.message:"Could not sign out.")}};
 const cloudSave=async()=>{try{if(!cloudConfigured){setCloudMsg("Cloud database is not configured.");return}await cloudSaveCharacter(c);setCloudMsg("✓ Character saved to cloud database.")}catch(e){setCloudMsg(e instanceof Error?e.message:"Cloud save failed.")}};
 const cloudLoad=async()=>{try{if(!cloudConfigured){setCloudMsg("Cloud database is not configured.");return}const saved=await cloudGetCharacter();if(saved)setC(normalize(saved));setCloudMsg(saved?"✓ Character loaded from cloud database.":"No cloud character found yet.")}catch(e){setCloudMsg(e instanceof Error?e.message:"Cloud load failed.")}};
 return <><section className="section-head"><div><h2>Account</h2><p>Real Supabase authentication and cloud character storage.</p></div><span className="pill">{pro?"⭐ Playtest Pro":"Free"}</span></section>
 <Card title={user?"Signed in":"Cloud Account"}>
 {user?<><div className="review"><h3>{user.user_metadata?.display_name||name||"Player"}</h3><p>{user.email}</p><p className="success">✓ Real cloud account is connected.</p><p className="hint">Your character can now be saved and loaded across devices using this account.</p></div><div className="buttonrow"><button onClick={cloudSave}>☁️ Save Character to Cloud</button><button onClick={cloudLoad}>↙ Load Character</button><button onClick={signout}>Log Out</button></div></>:<>
 <div className="buttonrow"><button className={mode==="signup"?"active":""} onClick={()=>setMode("signup")}>Create Account</button><button className={mode==="login"?"active":""} onClick={()=>setMode("login")}>Log In</button></div>
 <div className="formgrid">{mode==="signup"&&<Field label="Display Name" value={name} onChange={setName} placeholder="Crawler name"/>}<Field label="Email" value={email} onChange={setEmail} type="email" placeholder="you@example.com"/><Field label="Password" value={password} onChange={setPassword} type="password" placeholder="At least 6 characters"/></div>
 <button onClick={save}>{mode==="signup"?"Create Cloud Account":"Log In to Cloud"}</button>
 </>}
 {cloudMsg&&<p className={cloudMsg.startsWith("✓")?"success":"hint"}>{cloudMsg}</p>}
 </Card>
 {user&&<Card title="Cloud Database"><p className="hint">Supabase is connected. Character data is protected by row-level security and belongs to the signed-in account.</p><div className="buttonrow"><button onClick={cloudSave}>☁️ Save Character to Cloud</button><button onClick={cloudLoad}>☁️ Load Character from Cloud</button></div></Card>}
 <Card title="Pricing — planned"><div className="pricing"><div><h3>Free</h3><p>Character, dice, basic combat, inventory, campaign joining.</p><b>$0</b></div><div><h3>Pro</h3><p>Unlimited characters, full GM tools, campaign management, advanced tools.</p><b>$2.99/mo or $29.99/yr</b></div></div></Card>
 </>
}
function CampaignPage(){
 const [campaigns,setCampaigns]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem("cc-campaigns")||"[]")}catch{return []}});
 const [title,setTitle]=useState(""); const [code,setCode]=useState(""); const [joined,setJoined]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem("cc-joined")||"[]")}catch{return []}});
 const persist=(next:any[])=>{setCampaigns(next);localStorage.setItem("cc-campaigns",JSON.stringify(next))};
 const make=()=>{const t=title.trim()||"My Crawler Campaign";const c=Math.random().toString(36).slice(2,6).toUpperCase()+"-"+Math.random().toString(36).slice(2,6).toUpperCase();persist([...campaigns,{id:crypto.randomUUID?.()||Date.now().toString(),title:t,code:c,owner:localStorage.getItem("cc-user")||"Account",players:0}]);setTitle("")};
 const join=()=>{const c=code.trim().toUpperCase();const found=campaigns.find(x=>x.code===c);if(found&&!joined.includes(found.id)){const j=[...joined,found.id];setJoined(j);localStorage.setItem("cc-joined",JSON.stringify(j));setCode("")}};
 return <><section className="section-head"><div><h2>Campaign Hub</h2><p>Create a campaign, invite players with a code, and keep the party together. No GM field is required.</p></div><span className="pill">Playtest ready</span></section>
 <div className="gm-grid"><Card title="🎮 Create Campaign"><Field label="Campaign Name" value={title} onChange={setTitle} placeholder="Friday Night Crawlers"/><button onClick={make}>Create Campaign + Invite Code</button><p className="hint">No GM field. Campaign ownership is automatic; roles can be assigned after players join.</p></Card><Card title="🎟️ Join Campaign"><Field label="Invite Code" value={code} onChange={setCode} placeholder="AB12-CD34"/><button onClick={join}>Join Campaign</button><p className="hint">Your GM gives you the code. No shared password needed.</p></Card></div>
 <Card title="Your Campaigns">{campaigns.length===0?<p className="hint">No campaigns on this device yet. Create one above.</p>:campaigns.map(x=><div className="generator-result" key={x.id}><b>{x.title}</b><span>Owner: {x.owner} • Invite: <strong>{x.code}</strong></span><p>{joined.includes(x.id)?"✓ You joined this campaign.":"Share this code with your players."}</p><div className="buttonrow"><button onClick={()=>navigator.clipboard?.writeText(x.code)}>Copy Code</button><button onClick={()=>navigator.share?.({title:x.title,text:`Join my Crawler Companion campaign with code ${x.code}`})}>Share</button></div></div>)}</Card>
 <Card title="Architecture"><p className="hint">Current build proves the campaign flow locally. The next backend connection will make accounts, characters, party HP, and GM changes sync across devices in real time.</p></Card>
 </>
}

function Landing(){return <div className="landing"><div className="landing-glow"/><div className="landing-card"><div className="dragon-mark" aria-hidden="true">🐉</div><div className="landing-kicker">GINGER DRAGON FIRE STUDIOS</div><h1>Ginger Dragon Fire</h1><p className="landing-tagline">Games • Software • Adventures</p><p className="landing-copy">A home for the tools, games, and adventures we forge. Choose an app below.</p><div className="landing-apps"><a className="landing-app" href="/crawler-companion"><div className="landing-app-icon">🔥</div><div><b>Crawler Companion</b><span>Digital tabletop campaign companion</span></div><strong>Launch →</strong></a><div className="landing-app coming"><div className="landing-app-icon">⚔️</div><div><b>More adventures coming</b><span>New Ginger Dragon Fire projects will appear here.</span></div><strong>Coming Soon</strong></div></div><div className="landing-features"><span>⚔️ Games</span><span>🛠️ Software</span><span>🔥 Adventures</span><span>🐉 Original Worlds</span></div><div className="landing-note">Independent studio • Built by Ginger Dragon Fire Studios</div></div></div>}

function App(){const [tab,setTab]=useState<Tab>("Dashboard");const [c,setC]=useState<Character>(()=>normalize(blank()));const [path,setPath]=useState(()=>window.location.pathname.replace(/\/$/,"")||"/");useEffect(()=>{const onPop=()=>setPath(window.location.pathname.replace(/\/$/,"")||"/");window.addEventListener("popstate",onPop);return()=>window.removeEventListener("popstate",onPop)},[]);useEffect(()=>{try{const r=localStorage.getItem("crawler-character-v2");if(r)setC(normalize(JSON.parse(r)))}catch{}},[]);useEffect(()=>{try{localStorage.setItem("crawler-character-v2",JSON.stringify(c))}catch{}},[c]);const update=(f:(x:Character)=>Character)=>setC(x=>normalize(f(normalize(x))));if(path!=="/crawler-companion")return <Landing/>;return <div className="app"><header><div><span className="eyebrow">GINGER DRAGON FIRE STUDIOS</span><h1>🐉 Ginger Dragon Fire</h1></div><div className="header-right"><span className="save">✓ Saved on this device</span><span className="pill">Beta Candidate</span><button onClick={()=>setTab("Account")}>👤 {localStorage.getItem("cc-user")||"Account"}</button></div></header><nav aria-label="Primary navigation">{tabs.map(t=><button className={tab===t?"active":""} key={t} onClick={()=>setTab(t)}>{t}</button>)}</nav><main>{tab==="Dashboard"&&<Dashboard c={c} update={update} setTab={setTab}/>} {tab==="Character"&&<><CharacterPage c={c} update={update}/><DataTools c={c} setC={setC}/></>} {tab==="Combat"&&<Combat c={c} update={update}/>} {tab==="Inventory"&&<Inventory c={c} update={update}/>} {tab==="Equipment"&&<Equipment c={c} update={update}/>} {tab==="Progression"&&<Progression c={c} update={update}/>} {tab==="Dice"&&<Dice/>} {tab==="Party"&&<Party/>} {tab==="GM Tools"&&<GM/>} {tab==="Rulebook"&&<Rulebook/>} {tab==="Campaign"&&<CampaignPage/>} {tab==="Account"&&<AccountPage c={c} setC={setC}/>}</main><footer><span>Ginger Dragon Fire Studios • Tabletop Companion</span><span><a href="/privacy.html">Privacy</a> · <a href="/support.html">Support</a> · </span></footer></div>}
createRoot(document.getElementById("root")!).render(<ErrorBoundary><App/></ErrorBoundary>);
